#[test]
fn unit_metadata() {
    let info = ThermalResistance::<f64>::INFO;
    assert_eq!(info.name, "ThermalResistance");
    assert_eq!(info.units.len(), ThermalResistanceUnit::ALL.len());
    for (&unit, unit_info) in ThermalResistanceUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, ThermalResistanceUnit::KelvinPerWatt.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ThermalResistance::new(v, ThermalResistanceUnit::KelvinPerWatt),
        ThermalResistance::from_kelvins_per_watt(v)
    );
    assert_eq!(
        ThermalResistance::from_base(v).convert_to(ThermalResistanceUnit::KelvinPerWatt),
        ThermalResistance::from_base(v).as_kelvins_per_watt()
    );
    assert_eq!(
        ThermalResistance::new(v, ThermalResistanceUnit::DegreeCelsiusPerWatt),
        ThermalResistance::from_degrees_celsius_per_watt(v)
    );
    assert_eq!(
        ThermalResistance::from_base(v).convert_to(ThermalResistanceUnit::DegreeCelsiusPerWatt),
        ThermalResistance::from_base(v).as_degrees_celsius_per_watt()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ThermalResistance; 2] = [
        ThermalResistance::const_new(1234.5, ThermalResistanceUnit::KelvinPerWatt),
        ThermalResistance::const_new(1234.5, ThermalResistanceUnit::DegreeCelsiusPerWatt),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ThermalResistanceUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ThermalResistance::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ThermalResistanceUnit::ALL {
            assert_eq!(
                ThermalResistance::const_new(v, unit).as_base().to_bits(),
                ThermalResistance::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ThermalResistance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ThermalResistance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ThermalResistanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ThermalResistance::from_base(0.0).auto_unit().unit,
        ThermalResistanceUnit::KelvinPerWatt
    );
}

